package fractalrabbit.simulation;

import com.google.common.graph.MutableValueGraph;
import com.google.common.graph.ValueGraphBuilder;
import fractalrabbit.geometry.SpacePointGenerator;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Random;

/**
 * Agoraphobic point process on a rooted tree, generated by hard-threshold rejection.
 * The root is the origin.
 *
 * @author rwdarli
 * @see SpacePointGenerator
 */
public class AgoraphobicPoints {
    private final int pointCount;
    private final double innovation;
    private final SpacePointGenerator pointGenerator;
    private final List<double[]> points = new ArrayList<>();
    private final MutableValueGraph<double[], Double> rootedTree = ValueGraphBuilder.directed().build();
    private final double[] radialBounds;
    private final Random random;
    private int totalSamples;

    /**
     * @param n     number of points to create
     * @param d     Euclidean dimension
     * @param h     fractal dimension of the limit set, less than {@code d}
     * @param theta non-negative rate at which additional clumps form
     */
    public AgoraphobicPoints(int n, int d, double h, double theta) {
        pointCount = n;
        innovation = theta;
        pointGenerator = new SpacePointGenerator(d);
        radialBounds = new double[n];
        Arrays.setAll(radialBounds, index -> index > 0 ? Math.pow(index, -1.0 / h) : 1.0);
        random = new Random();
        double[] origin = pointGenerator.zeroVector();
        points.add(origin);
        rootedTree.addNode(origin);
    }

    /**
     * Fills the point set. A new clump is rooted at the origin; otherwise a parent
     * is chosen uniformly and the candidate is kept with probability one over the
     * number of points already inside its ball.
     */
    public void generatePoints() {
        totalSamples = 1;
        for (int index = 1; index < pointCount; index++) {
            if (random.nextDouble() < innovation / (innovation + index)) {
                addChildOfRoot(index);
            } else {
                addPointNearRandomParent(index);
            }
        }
    }

    /**
     * @return points in generation order, starting with the origin
     */
    public List<double[]> getPoints() {
        return points;
    }

    /**
     * @return parent-child tree; edge values are Euclidean lengths
     */
    public MutableValueGraph<double[], Double> getRootedTree() {
        return rootedTree;
    }

    /**
     * @return fraction of proposals that were accepted, including the root
     */
    public double getSamplingEfficiency() {
        return (double) pointCount / totalSamples;
    }

    private void addChildOfRoot(int index) {
        points.add(pointGenerator.samplePointUnitDisk());
        totalSamples++;
        double[] child = points.get(index);
        rootedTree.putEdgeValue(points.getFirst(), child, Math.sqrt(pointGenerator.sumSquares(child)));
    }

    private void addPointNearRandomParent(int index) {
        double radius = radialBounds[index];
        while (true) {
            int parent = random.nextInt(index);
            double[] candidate = pointGenerator.sampleNearbyPoint(radius, points.get(parent));
            totalSamples++;
            int neighborCount = 0;
            for (double[] existing : points) {
                if (SpacePointGenerator.euclideanDistance(existing, candidate) < radius) {
                    neighborCount++;
                }
            }
            double acceptanceProbability = neighborCount == 0 ? 1.0 : 1.0 / neighborCount;
            if (random.nextDouble() < acceptanceProbability) {
                points.add(candidate);
                rootedTree.putEdgeValue(
                        points.get(parent),
                        points.get(index),
                        SpacePointGenerator.euclideanDistance(points.get(parent), points.get(index)));
                return;
            }
        }
    }
}
